// %B is an output-only memref; %C is used by a return.
func.func @f(%A : memref<MxKxf32>,
             %B : memref<MxKxf32>,
             %C : memref<MxNxf32>) -> memref<MxNxf32> {
  linalg.copy   ins(%A : memref<MxKxf32>)  outs(%B : memref<MxKxf32>)   // side-effecting: writes %B
  linalg.matmul ins(%A, %W : memref<MxKxf32>, memref<KxNxf32>)
                outs(%C : memref<MxNxf32>)                              // side-effecting: writes %C, and %C escapes
  %tmp = arith.addf %z, %z : f32                                        // pure, %tmp unused
  return %C : memref<MxNxf32>
}

// Pseudo IR (Aten-like)
// BEFORE (NCHW contiguous)
%x : Tensor<16x3x224x224xf32, strides=[150528,50176,224,1]>

// TARGET (channels_last strides on the same logical shape)
%y : Tensor<16x3x224x224xf32, strides=[150528,1,672,3]>

// Storage index formula for element (n, c, h, w):
//   NCHW-contiguous: n*C*H*W + c*H*W + h*W + w
//   channels_last : n*C*H*W + h*W*C + w*C + c
// These two orderings place different elements in a given physical byte;
// hence a pure view (no data movement) cannot rewrite one into the other.

// BEFORE
%y = "mydialect.matmul"(%a, %b) :
       (tensor<?x?xf32>, tensor<?x?xf32>) -> tensor<?x?xf32>

// AFTER (partial legalization)
%ma = bufferization.to_memref %a : memref<?x?xf32>
%mb = bufferization.to_memref %b : memref<?x?xf32>
%mc = memref.alloc() : memref<?x?xf32>
func.call @extern_gemm(%ma, %mb, %mc) :
  (memref<?x?xf32>, memref<?x?xf32>, memref<?x?xf32>) -> ()
%y = bufferization.to_tensor %mc : memref<?x?xf32>

// ConversionTarget:
//   addLegalDialect<func, memref, bufferization>
//   addIllegalOp<mydialect::MatmulOp>
// TypeConverter:
//   addConversion(tensor -> memref via bufferization materialization)

// BEFORE (pseudo-IR, imperative)
func @f(%a: memref<N x f32>, %b: memref<N x f32>,
        %c: memref<1 x f32>, %d: memref<1 x f32>) {
  scf.for %i = 0 to N step 1 {
    %inv = arith.mulf (load %c[0]) (load %d[0]) : f32
    %v   = arith.addf (load %b[%i]) %inv     : f32
    store %v, %a[%i]
  }
}

// AFTER (LICM applied)
func @f(%a, %b, %c, %d) {
  %t = arith.mulf (load %c[0]) (load %d[0]) : f32
  scf.for %i = 0 to N step 1 {
    %v = arith.addf (load %b[%i]) %t : f32
    store %v, %a[%i]
  }
}

// Matmul via linalg.generic
#matmul_maps = [
  affine_map<(m, n, k) -> (m, k)>,   // A[m, k]
  affine_map<(m, n, k) -> (k, n)>,   // B[k, n]
  affine_map<(m, n, k) -> (m, n)>    // C[m, n]
]
linalg.generic {
  indexing_maps = #matmul_maps,
  iterator_types = ["parallel", "parallel", "reduction"]
} ins(%A, %B : tensor<MxKxf32>, tensor<KxNxf32>)
  outs(%C : tensor<MxNxf32>) {
^bb0(%a : f32, %b : f32, %c : f32):
  %ab = arith.mulf %a, %b : f32
  %s  = arith.addf %c, %ab : f32
  linalg.yield %s : f32
} -> tensor<MxNxf32>

// BEFORE
affine.for %i = 0 to M {
  affine.for %j = 0 to N {
    %v = affine.load %B[%i, %j] : memref<MxNxf32>
    affine.store %v, %C[%i, %j] : memref<MxNxf32>
  }
}

// AFTER (proposed)
affine.for %j = 0 to N {
  affine.for %i = 0 to M {
    %v = affine.load %B[%i, %j] : memref<MxNxf32>
    affine.store %v, %C[%i, %j] : memref<MxNxf32>
  }
}

// L0: linalg-on-tensor (declarative)
%0 = linalg.matmul ins(%A, %B : tensor<MxKxf32>, tensor<KxNxf32>)
                   outs(%C : tensor<MxNxf32>) -> tensor<MxNxf32>

// L1: after bufferization -> linalg-on-memref
linalg.matmul ins(%A, %B : memref<MxKxf32>, memref<KxNxf32>)
              outs(%C : memref<MxNxf32>)

// L2: after conversion to scf + affine loads/stores
scf.for %i = %c0 to %M step %c1 {
  scf.for %j = %c0 to %N step %c1 {
    scf.for %k = %c0 to %K step %c1 {
      %a = memref.load %A[%i, %k] : memref<MxKxf32>
      %b = memref.load %B[%k, %j] : memref<KxNxf32>
      %c = memref.load %C[%i, %j] : memref<MxNxf32>
      %m = arith.mulf %a, %b : f32
      %s = arith.addf %c, %m : f32
      memref.store %s, %C[%i, %j] : memref<MxNxf32>
    }
  }
}

questions.stem:
Consider the following graph-level IR transformation where a symbolic-shape function is specialized to concrete shapes at compile time:

BEFORE (symbolic):
```
func f(x : Tensor[N, K, f16], w : Tensor[K, M, f16]) -> Tensor[N, M, f16]:
    return matmul(x, w)
```
AFTER (specialized to N=32, K=4096, M=4096):
```
func f_32x4096x4096(x : Tensor[32, 4096, f16], w : Tensor[4096, 4096, f16]) -> Tensor[32, 4096, f16]:
    return matmul(x, w)
```
Which statement about this specialization is correct?

