// Static shape
%y = stablehlo.add %x, %x : tensor<4x8xf32>

// Dynamic shape (bounded) — bounds encoded on the type
%z = stablehlo.dynamic_broadcast_in_dim %s,
         dims = [0, 1] :
         (tensor<f32>) -> tensor<?x?xf32, #stablehlo.bounds<[128, 128]>>

// Portability contract: same op set consumed by multiple compilers/hardware
// (XLA-CPU, XLA-GPU, XLA-TPU, PJRT plugins, IREE, ...)

# Compute (unchanged across schedules):
#   C[i, j] = sum_k A[i, k] * B[k, j]  for i in [0,M), j in [0,N)

# Schedule (tile i by TI=32, j by TJ=32):
s.split(i, factor=32)  # -> i.o, i.i
s.split(j, factor=32)  # -> j.o, j.i
s.reorder(i.o, j.o, i.i, j.i, k)

# Resulting loop nest (semantically equivalent to the compute):
for i.o in 0..M/32:
  for j.o in 0..N/32:
    for i.i in 0..32:
      for j.i in 0..32:
        for k in 0..K:
          C[i.o*32 + i.i, j.o*32 + j.i] += A[i.o*32 + i.i, k] * B[k, j.o*32 + j.i]

// During partial conversion, an op that was rewritten to memref feeds into an unconverted op still expecting tensor.
// The Dialect Conversion driver inserts an `unrealized_conversion_cast` at the boundary and asks the
// TypeConverter for a materialization to legalize the cast into a real op.

// Example boundary insertion (pre-materialization):
%m0 = memref.alloc() : memref<Nxf32>
// ... writes into %m0 via new memref-based ops ...
%t0 = builtin.unrealized_conversion_cast %m0 : memref<Nxf32> to tensor<Nxf32>

// Materialization (via `addTargetMaterialization` inserting bufferization.to_tensor):
%t0 = bufferization.to_tensor %m0 : memref<Nxf32>

// After pass P
func.func @f(%x : tensor<4xf32>) -> tensor<4xf32> {
  %c = arith.constant dense<1.0> : tensor<4xf32>
  %y = "tosa.add"(%x, %c) :
         (tensor<4xf32>, tensor<8xf32>) -> tensor<4xf32>  // <-- verifier error
  return %y : tensor<4xf32>
}

// Verifier message (excerpt):
//   error: 'tosa.add' op requires operands to have compatible shapes; got
//     'tensor<4xf32>' and 'tensor<8xf32>'
//   note: see this operation:
//     %y = "tosa.add" ...

// (i) transpose (1,2)
%x  : tensor<2x3x4xf32, strides=[12,4,1]>
%x1 : tensor<2x4x3xf32, strides=[12,1,4]>       // pure view: shape/stride swap

// (ii) reshape(6,4) on the contiguous [2,3,4]
%x  : tensor<2x3x4xf32, strides=[12,4,1]>
%x2 : tensor<6x4xf32,   strides=[4,1]>           // pure view: fold outer dims

// (iii) reshape(4,6) on the contiguous [2,3,4]
// Requires a re-index that a single (shape, stride) pair cannot express; needs copy
%x3 : tensor<4x6xf32> = materialize(reshape %x to [4,6])
